222	function buyInvStock(symbol, shares) {
223	  const state = StateManager.getState();
224	  const inv = state.investment;
225	  const m = inv.stockMarket[symbol];
226	  if (!m) return;
227	  const cost = Math.round(m.price * shares * 100) / 100;
228	  if (state.resources.cash < cost) {
229	    StateManager.addMessage("现金不足", "danger");
230	    return;
231	  }
232	  state.resources.cash -= cost;
233	  const h = inv.stockHoldings.find((s) => s.symbol === symbol);
234	  if (h) {
235	    const total = h.shares + shares;
236	    h.avgPrice =
237	      Math.round(((h.avgPrice * h.shares + cost) / total) * 100) / 100;
238	    h.shares = total;
239	  } else inv.stockHoldings.push({ symbol, shares, avgPrice: m.price });
240	  StateManager.addMessage("买入 " + symbol + " " + shares + "股", "success");
241	}
242	
243	function sellInvStock(symbol, shares) {
244	  const state = StateManager.getState();
245	  const inv = state.investment;
246	  const h = inv.stockHoldings.find((s) => s.symbol === symbol);
247	  if (!h || h.shares < shares) {
248	    StateManager.addMessage("持仓不足", "danger");
249	    return;
250	  }
251	  const m = inv.stockMarket[symbol];
252	  const revenue = Math.round(m.price * shares * 100) / 100;
253	  state.resources.cash += revenue;
254	  h.shares -= shares;
255	  if (h.shares <= 0)
256	    inv.stockHoldings = inv.stockHoldings.filter((s) => s.symbol !== symbol);
257	  StateManager.addMessage("卖出 " + symbol + " " + shares + "股", "success");
258	}
