260	function buyBtc(amount) {
261	  const state = StateManager.getState();
262	  const inv = state.investment;
263	  const cost = Math.round(inv.btcPrice * amount * 100) / 100;
264	  if (state.resources.cash < cost) {
265	    StateManager.addMessage("现金不足", "danger");
266	    return;
267	  }
268	  state.resources.cash -= cost;
269	  inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
270	  StateManager.addMessage("买入 " + amount + " BTC", "success");
271	}
