273	function sellBtc(amount) {
274	  const state = StateManager.getState();
275	  const inv = state.investment;
276	  if (inv.btcHoldings < amount) {
277	    StateManager.addMessage("持仓不足", "danger");
278	    return;
279	  }
280	  state.resources.cash += Math.round(inv.btcPrice * amount * 100) / 100;
281	  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
282	  StateManager.addMessage("卖出 " + amount + " BTC", "success");
283	}
