285	function buyProperty(propId) {
286	  const state = StateManager.getState();
287	  const inv = state.investment;
288	  const prop = PROPERTIES.find((p) => p.id === propId);
289	  if (!prop) return;
290	  if (state.resources.cash < prop.price) {
291	    StateManager.addMessage("现金不足", "danger");
292	    return;
293	  }
294	  state.resources.cash -= prop.price;
295	  inv.properties.push({
296	    ...prop,
297	    buyPrice: prop.price,
298	    currentPrice: prop.price,
299	    buyDay: state.player.day,
300	  });
301	  StateManager.addMessage("购入" + prop.name, "success");
302	}
