304	function sellProperty(propId) {
305	  const state = StateManager.getState();
306	  const inv = state.investment;
307	  const idx = inv.properties.findIndex((p) => p.id === propId);
308	  if (idx < 0) return;
309	  const prop = inv.properties[idx];
310	  const net = prop.currentPrice - Math.round(prop.currentPrice * 0.05);
311	  state.resources.cash += net;
312	  inv.properties.splice(idx, 1);
313	  StateManager.addMessage("出售" + prop.name + " 到手" + net, "success");
314	}
