316	function buyCar(carId) {
317	  const state = StateManager.getState();
318	  const inv = state.investment;
319	  const car = CAR_TYPES.find((c) => c.id === carId);
320	  if (!car) return;
321	  if (state.resources.cash < car.price) {
322	    StateManager.addMessage("现金不足", "danger");
323	    return;
324	  }
325	  state.resources.cash -= car.price;
326	  inv.cars.push({
327	    ...car,
328	    buyPrice: car.price,
329	    currentPrice: car.price,
330	    buyDay: state.player.day,
331	  });
332	  state.player.maxActionPoints =
333	    (state.player.maxActionPoints || 100) + car.travelBonus;
334	  state.player.actionPoints = Math.min(
335	    state.player.maxActionPoints,
336	    state.player.actionPoints + car.travelBonus,
337	  );
338	  StateManager.addMessage(
339	    "购入" + car.name + " 行动力上限+" + car.travelBonus,
340	    "success",
341	  );
342	}
