5	/** 执行职场行动 */
6	function doCorporateAction(actionId) {
7	  const state = StateManager.getState();
8	  const action = CORP_ACTIONS.find((a) => a.id === actionId);
9	  if (!action) return false;
10	
11	  // 检查职级要求
12	  if (action.requiresRank) {
13	    const rankIndex = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
14	      state.corporate.rank,
15	    );
16	    const requiredIndex = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
17	      action.requiresRank,
18	    );
19	    if (rankIndex < requiredIndex) {
20	      StateManager.addMessage(
21	        `⚠️ 需要${action.requiresRank}以上才能执行此操作。`,
22	        "warning",
23	      );
24	      return false;
25	    }
26	  }
27	
28	  // 检查费用
29	  if (action.cost && state.resources.cash < action.cost) {
30	    StateManager.addMessage(`⚠️ 需要 ¥${action.cost}，现金不足。`, "warning");
31	    return false;
32	  }
33	
34	  // 特殊处理：股票交易
35	  if (action.special === "stock") {
36	    showStockTradeModal();
37	    return true;
38	  }
39	
40	  // 扣费
41	  if (action.cost) {
42	    state.resources.cash -= action.cost;
43	  }
44	
45	  // 应用效果（Q4冲刺KPI+50%）
46	  const c = state.player.corporate;
47	  const effects = action.effects;
48	  const sprintBonus = state.flags.q4Sprint ? 1.5 : 1;
49	  if (effects.kpi)
50	    c.kpi = Math.max(
51	      0,
52	      Math.min(150, c.kpi + Math.round(effects.kpi * sprintBonus)),
53	    );
54	  if (effects.ability)
55	    c.ability = Math.max(0, Math.min(100, c.ability + effects.ability));
56	  if (effects.hair) c.hair = Math.max(0, Math.min(100, c.hair + effects.hair));
57	  if (effects.dignity)
58	    c.dignity = Math.max(0, Math.min(100, c.dignity + effects.dignity));
59	  if (effects.upwardMgmt)
60	    c.upwardMgmt = Math.max(
61	      0,
62	      Math.min(100, c.upwardMgmt + effects.upwardMgmt),
63	    );
64	  if (effects.popularity)
65	    c.popularity = Math.max(
66	      0,
67	      Math.min(100, c.popularity + effects.popularity),
68	    );
69	  if (effects.risk) c.risk = Math.max(0, Math.min(100, c.risk + effects.risk));
70	  if (effects.fatigue)
71	    state.needs.fatigue = Math.max(
72	      0,
73	      Math.min(100, state.needs.fatigue + effects.fatigue),
74	    );
75	  if (effects.happiness)
76	    state.needs.happiness = Math.max(
77	      0,
78	      Math.min(100, state.needs.happiness + effects.happiness),
79	    );
80	  if (effects.intelligence)
81	    state.player.intelligence = Math.min(
82	      100,
83	      state.player.intelligence + effects.intelligence,
84	    );
85	
86	  state.corporate.actionsUsed++;
87	  StateManager.addMessage(`${action.icon} ${action.name}完成！`, "success");
88	
89	  // 检查季度是否用完
90	  const rankData = CORP_RANKS[state.corporate.rank];
91	  const maxActions = rankData ? rankData.maxActions : 3;
92	  if (state.corporate.actionsUsed >= maxActions) {
93	    endQuarter();
94	  }
95	
96	  return true;
97	}
