286	  state.player.corporate.upwardMgmt = 20;
287	  state.player.corporate.kpi = 20;
288	  state.player.corporate.ability = Math.min(100, Math.round(state.player.intelligence * 0.8 + 10));
289	  state.player.corporate.risk = 0;
290	  state.player.corporate.popularity = 25;
291	
292	  // 回到城中村
293	  state.housing.tier = Math.max(0, state.housing.tier - 2);
294	  const baseCap = [20, 50, 100, 200][state.housing.tier] || 20;
295	  state.inventory.capacity = baseCap + (state.housing.storageCapacity || 0);
296	
297	  StateManager.addMessage(
298	    `🔄 你被开除，回到了街头。遣散费 ¥${severance.toLocaleString()}。`,
299	    "warning",
300	  );
301	  StateManager.addMessage(`📋 ${reason}`, "danger");
302	  StateManager.addMessage(
303	    "💡 但你在职场积累的技能和部分金钱还在。可以从街头商机中寻找新机会，或休整后再战职场。",
304	    "info",
305	  );
306	
307	  // 关闭弹窗
308	  document.querySelector(".modal-overlay")?.remove();
309	  currentTab = "actions";
310	  renderAll();
311	}
