432	        <span>20日高 ¥${market.high20.toFixed(2)}</span>
433	        <span>20日低 ¥${market.low20.toFixed(2)}</span>
434	      </div>
435	
436	      ${renderKLine(market.history, price)}
437	
438	      ${
439	        shares > 0
440	          ? `
441	        <div style="margin-top:8px;padding:6px 8px;background:rgba(0,180,216,0.06);border-radius:4px;font-size:11px;">
442	          <div style="display:flex;justify-content:space-between;">
443	            <span>持仓: <strong>${shares}</strong>股 | 均价 <strong>¥${holding.avgPrice.toFixed(2)}</strong></span>
444	            <span style="color:${pnlColor};font-weight:600;">${pnl >= 0 ? "+" : ""}¥${pnl.toLocaleString()} (${pnlPct >= 0 ? "+" : ""}${pnlPct.toFixed(1)}%)</span>
445	          </div>
446	        </div>
