5	/** 招聘团队成员 */
6	function hireTeamMember(memberTypeId) {
7	  const state = StateManager.getState();
8	  const rankData = CORP_RANKS[state.corporate.rank];
9	  if (!rankData || !rankData.canManageTeam) {
10	    StateManager.addMessage("⚠️ P7以上才能管理团队。", "warning");
11	    return false;
12	  }
13	  if (state.corporate.team.length >= (rankData.maxTeamSize || 5)) {
14	    StateManager.addMessage("⚠️ 团队已满员。", "warning");
15	    return false;
16	  }
17	
18	  const template = TEAM_MEMBERS.find((m) => m.id === memberTypeId);
19	  if (!template) return false;
20	
21	  // 招聘成本
22	  const cost = 10000;
23	  if (state.resources.cash < cost) {
24	    StateManager.addMessage(
25	      `⚠️ 招聘需要 ¥${cost.toLocaleString()}。`,
26	      "warning",
27	    );
28	    return false;
29	  }
30	
31	  state.resources.cash -= cost;
32	
33	  // 创建成员（加入随机性）
34	  const member = {
35	    ...template,
36	    productivity: template.productivity + Math.floor(Math.random() * 4) - 2,
37	    loyalty: template.loyalty + Math.floor(Math.random() * 10) - 5,
38	    hiredDay: state.player.day,
39	  };
40	
41	  state.corporate.team.push(member);
42	
43	  // 降低现有团队士气
44	  for (const m of state.corporate.team) {
45	    if (m !== member) m.loyalty = Math.max(0, m.loyalty - 3);
46	  }
47	
48	  StateManager.addMessage(
49	    `👥 招聘了 ${member.name}（${member.role}）加入团队！`,
50	    "success",
51	  );
52	  return true;
53	}
