55	/** 解雇团队成员 */
56	function fireTeamMember(index) {
57	  const state = StateManager.getState();
58	  if (index < 0 || index >= state.corporate.team.length) return false;
59	
60	  const member = state.corporate.team[index];
61	  state.corporate.team.splice(index, 1);
62	
63	  // 团队士气影响
64	  for (const m of state.corporate.team) {
65	    m.loyalty = Math.max(0, m.loyalty - 5);
66	  }
67	  state.player.corporate.popularity = Math.max(
68	    0,
69	    state.player.corporate.popularity - 5,
70	  );
71	
72	  StateManager.addMessage(`👋 ${member.name} 离开了团队。`, "warning");
73	  return true;
74	}
75	
76	/** 计算团队产出系数 */
77	function getTeamProductivity(state) {
78	  if (state.corporate.team.length === 0) return 1.0;
79	
80	  const totalProductivity = state.corporate.team.reduce(
81	    (s, m) => s + Math.max(1, m.productivity),
82	    0,
83	  );
84	  const avgLoyalty =
85	    state.corporate.team.reduce((s, m) => s + Math.max(1, m.loyalty), 0) /
86	    state.corporate.team.length;
87	  const sizeBonus = Math.min(1.5, 1 + state.corporate.team.length * 0.05);
88	
89	  return (
90	    (totalProductivity / state.corporate.team.length) *
91	    (avgLoyalty / 100) *
92	    sizeBonus
93	  );
94	}
