191	/** 更新股市价格（每日 / 季末） */
192	function updateStockPrices(state, forceNews = false) {
193	  for (const stock of STOCK_LIST) {
194	    const market = state.corporate.stockMarket[stock.symbol];
195	    if (!market) continue;
196	
197	    // 1) 基础趋势（每日漂移）
198	    const trend = stock.baseTrend;
199	    // 2) 随机扰动（正态分布近似）
200	    const noise = (Math.random() - 0.5) * 2 * stock.volatility;
201	    // 3) 均值回归（偏离20日均价过远时拉回一些）
202	    let meanReversion = 0;
203	    if (market.history.length >= 5) {
204	      const recent = market.history.slice(-5);
205	      const avg = recent.reduce((s, h) => s + h.price, 0) / recent.length;
206	      meanReversion = ((avg - market.price) / avg) * 0.15;
207	    }
208	    const change = 1 + trend + noise + meanReversion;
209	    market.price = Math.max(0.5, market.price * change);
210	    market.price = Math.round(market.price * 100) / 100;
211	
212	    // 4) 新闻冲击（5% 概率触发）
213	    if (forceNews || Math.random() < 0.05) {
214	      const newsPool = STOCK_NEWS_TEMPLATES.find(
215	        (n) => n.symbol === stock.symbol,
216	      );
217	      if (newsPool && state.player.day - market.lastNewsDay > 3) {
218	        const news =
219	          newsPool.headlines[
220	            Math.floor(Math.random() * newsPool.headlines.length)
221	          ];
222	        market.price = Math.max(0.5, market.price * (1 + news.impact));
223	        market.price = Math.round(market.price * 100) / 100;
224	        market.lastNewsDay = state.player.day;
225	        StateManager.addMessage(
226	          `📊 [${stock.symbol}] ${news.text}`,
227	          news.impact > 0 ? "success" : "danger",
228	        );
229	      }
230	    }
231	
232	    // 记录历史
233	    market.history.push({ day: state.player.day, price: market.price });
234	    if (market.history.length > 20) market.history.shift();
235	    market.high20 = Math.max(...market.history.map((h) => h.price));
236	    market.low20 = Math.min(...market.history.map((h) => h.price));
237	  }
238	}
