 99	/** 季度结束 */
100	function endQuarter() {
101	  const state = StateManager.getState();
102	  const c = state.corporate;
103	
104	  // 绩效考核
105	  const perfResult = calculatePerfScore(state);
106	  const grade = assignGrade(perfResult.score, state);
107	  c.perfHistory.push({
108	    year: state.player.corpYear,
109	    quarter: state.player.corpQuarter,
110	    grade: grade.grade,
111	    score: perfResult.score,
112	  });
113	
114	  // 追踪连续C
115	  if (grade.grade === "C") {
116	    c.consecutiveC++;
117	  } else {
118	    c.consecutiveC = 0;
119	  }
120	
121	  // 发放季度工资
122	  const rankData = CORP_RANKS[c.rank];
123	  const salary = rankData ? rankData.baseSalary * 3 : 45000;
124	  state.resources.cash += salary;
125	  state.resources.totalEarned += salary;
126	
127	  StateManager.addMessage(
128	    `💰 Q${c.corpQuarter} 结束。工资到账 ¥${salary.toLocaleString()}。绩效: ${grade.grade}`,
129	    "success",
130	  );
131	
132	  // Q1 年终奖（发放后清除冲刺标记）
133	  if (c.corpQuarter === 1 && c.perfHistory.length >= 4) {
134	    const bonusMultiplier =
135	      { "S+": 3, S: 2, A: 1.5, B: 1, C: 0 }[grade.grade] || 0;
136	    const bonus = Math.round(rankData.baseSalary * bonusMultiplier);
137	    if (bonus > 0) {
138	      state.resources.cash += bonus;
139	      StateManager.addMessage(
140	        `🎉 年终奖到账！绩效 ${grade.grade}，奖金 ¥${bonus.toLocaleString()}！`,
141	        "success",
142	      );
143	    }
144	    state.flags.q4Sprint = false;
145	  }
146	
147	  // Q4 冲刺（下季度 KPI 增益 +50%）
148	  if (c.corpQuarter === 4) {
149	    state.flags.q4Sprint = true;
150	    StateManager.addMessage(
151	      "🏃 进入Q4冲刺季！下季度所有KPI增益+50%，绩效评分×1.1。",
152	      "event",
153	    );
154	  }
155	
156	  // Q3 晋升判定
157	  if (c.corpQuarter === 3) {
158	    const promoResult = checkPromotion(state);
159	    if (promoResult) {
160	      applyPromotion(state, promoResult);
161	    }
162	  }
163	
164	  // 更新股票市场（延迟初始化+每季度行情刷新）
165	  if (
166	    typeof initStockMarket === "function" &&
167	    Object.keys(c.stockMarket || {}).length === 0
168	  ) {
169	    initStockMarket(state);
170	  }
171	  if (
172	    typeof updateStockPrices === "function" &&
173	    Object.keys(c.stockMarket || {}).length > 0
174	  ) {
175	    updateStockPrices(state, false);
176	  }
177	
178	  // 职场随机事件
179	  if (Math.random() < 0.2) {
180	    rollCorporateEvent(state);
181	  }
182	
183	  // 推进季度
184	  c.actionsUsed = 0;
185	  if (c.corpQuarter >= 4) {
186	    c.corpQuarter = 1;
187	    state.player.corpYear++;
188	    state.player.age++;
189	    StateManager.addMessage(
190	      `🎂 又一年过去了，你现在${state.player.age}岁了。`,
191	      "event",
192	    );
193	  } else {
194	    c.corpQuarter++;
195	  }
196	
197	  // 失败条件
198	  checkCorpLoseConditions(state);
199	  // 胜利条件
200	  checkCorpWinConditions(state);
201	
202	  autoSave();
203	}
