294	/** 卖出股票 */
295	function sellStock(symbol, shares) {
296	  const state = StateManager.getState();
297	  const holding = state.corporate.stocks.find((s) => s.symbol === symbol);
298	  if (!holding || holding.shares < shares) {
299	    StateManager.addMessage("⚠️ 持仓不足。", "danger");
300	    return false;
301	  }
302	
303	  const market = state.corporate.stockMarket[symbol];
304	  const revenue = Math.round(market.price * shares * 100) / 100;
305	  const profit = revenue - holding.avgPrice * shares;
306	
307	  state.resources.cash += revenue;
308	  state.resources.totalEarned += Math.max(0, profit);
309	
310	  holding.shares -= shares;
311	  if (holding.shares <= 0) {
312	    state.corporate.stocks = state.corporate.stocks.filter(
313	      (s) => s.symbol !== symbol,
314	    );
315	  }
316	
317	  const profitStr =
318	    profit >= 0
319	      ? `📈 盈利 ¥${Math.round(profit).toLocaleString()}`
320	      : `📉 亏损 ¥${Math.abs(Math.round(profit)).toLocaleString()}`;
321	  StateManager.addMessage(
322	    `💰 卖出 ${symbol} ×${shares}股，¥${revenue.toLocaleString()}。${profitStr}`,
323	    profit >= 0 ? "success" : "warning",
324	  );
325	  return true;
326	}
