342	/** 渲染简易 K 线（折线图 + 颜色块） */
343	function renderKLine(history, currentPrice) {
344	  if (!history || history.length < 2) {
345	    return '<div style="color:var(--text-muted);font-size:10px;">无历史数据</div>';
346	  }
347	  const prices = history.map((h) => h.price);
348	  const max = Math.max(...prices, currentPrice);
349	  const min = Math.min(...prices, currentPrice);
350	  const range = max - min || 1;
351	  const w = 140; // svg width
352	  const h = 40; // svg height
353	  const stepX = w / (history.length - 1);
354	  const points = history
355	    .map((p, i) => {
356	      const x = i * stepX;
357	      const y = h - ((p.price - min) / range) * h;
358	      return `${x.toFixed(1)},${y.toFixed(1)}`;
359	    })
360	    .join(" ");
361	
362	  const firstPrice = history[0].price;
363	  const lastPrice = history[history.length - 1].price;
364	  const lineColor =
365	    lastPrice >= firstPrice ? "var(--success)" : "var(--danger)";
366	  const fillColor =
367	    lastPrice >= firstPrice ? "rgba(46,204,113,0.12)" : "rgba(231,76,60,0.12)";
368	
369	  // 构造一个 polygon 用于填充
370	  const fillPoints = `0,${h} ${points} ${w},${h}`;
371	
372	  return `
373	    <svg width="${w}" height="${h}" style="display:block;margin-top:4px;">
374	      <polygon points="${fillPoints}" fill="${fillColor}" />
375	      <polyline points="${points}" fill="none" stroke="${lineColor}" stroke-width="1.5" />
376	    </svg>
377	  `;
378	}
