211	function checkCorpLoseConditions(state) {
212	  const c = state.player.corporate;
213	  const corp = state.corporate;
214	
215	  // 尊严归零 -> 精神崩溃（不可逆，Game Over）
216	  if (c.dignity <= 0) {
217	    state.flags.gameOver = true;
218	    state.flags.gameOverReason =
219	      "尊严耗尽——长期的精神压力让你选择了离开这个世界...";
220	    showGameOverModal();
221	    return true;
222	  }
223	
224	  // 35岁危机 -> P8以下不可逆淘汰
225	  if (state.player.age >= 35) {
226	    const rankIdx = ["P5", "P6", "P7", "P8", "P9", "P10"].indexOf(
227	      state.corporate.rank,
228	    );
229	    if (rankIdx < 3) {
230	      state.flags.gameOver = true;
231	      state.flags.gameOverReason = `35岁危机——${state.player.age}岁了还只是${state.corporate.rank}，被公司优化了...`;
232	      showGameOverModal();
233	      return true;
234	    }
235	  }
236	
237	  // 以下情况触发「被开除回街头」降级而非 Game Over
238	  let downgradeReason = null;
239	
240	  if (c.hair <= 0) {
241	    downgradeReason =
242	      "过劳到发量归零，被公司劝退休养。你回到了城中村重新开始。";
243	  }
244	  if (c.risk >= 100) {
245	    downgradeReason = "风险值爆表——触碰合规红线，被公司开除。你回到了街头。";
246	  }
247	  if (corp.consecutiveC >= 8) {
248	    downgradeReason = "连续2年绩效为C，被末位淘汰。你带着简历回到了城中村。";
249	  }
250	
251	  if (downgradeReason) {
252	    downgradeToStreet(state, downgradeReason);
253	    return true;
254	  }
255	
256	  return false;
257	}
