259	/**
260	 * 降级：从职场阶段回到街头
261	 * 保留部分资产和技能，重置职场属性
262	 */
263	function downgradeToStreet(state, reason) {
264	  const rankData = CORP_RANKS[state.corporate.rank] || CORP_RANKS.P5;
265	
266	  // 保留遣散费：季度工资的1-3倍
267	  const severance =
268	    rankData.baseSalary * 3 * (1 + Math.floor(Math.random() * 3));
269	  state.resources.cash += severance;
270	
271	  // 保留职场期间累积的投资
272	  // 重置职场状态
273	  state.player.phase = "street";
274	  state.corporate.rank = "P5";
275	  state.corporate.actionsUsed = 0;
276	  state.corporate.consecutiveC = 0;
277	  state.corporate.perfHistory = [];
278	  state.corporate.completedProjects = [];
279	  state.corporate.team = [];
280	  state.player.corpYear = 0;
281	  state.player.corpQuarter = 1;
282	  state.trade.currentLocation = "slum";
283	
284	  // 重置职场7维属性（保留部分能力作为积累）
285	  state.player.intelligence = Math.min(100, state.player.intelligence + 5);
286	  state.player.corporate.hair = 100;
287	  state.player.corporate.dignity = Math.min(
288	    100,
289	    Math.round(state.player.mental * 1.2),
290	  );
291	  state.player.corporate.upwardMgmt = 20;
292	  state.player.corporate.kpi = 20;
293	  state.player.corporate.ability = Math.min(
294	    100,
295	    Math.round(state.player.intelligence * 0.8 + 10),
296	  );
297	  state.player.corporate.risk = 0;
298	  state.player.corporate.popularity = 25;
299	
300	  // 回到城中村
301	  state.housing.tier = Math.max(0, state.housing.tier - 2);
302	  const baseCap = [20, 50, 100, 200][state.housing.tier] || 20;
303	  state.inventory.capacity = baseCap + (state.housing.storageCapacity || 0);
304	
305	  StateManager.addMessage(
306	    `🔄 你被开除，回到了街头。遣散费 ¥${severance.toLocaleString()}。`,
307	    "warning",
308	  );
309	  StateManager.addMessage(`📋 ${reason}`, "danger");
310	  StateManager.addMessage(
311	    "💡 但你在职场积累的技能和部分金钱还在。可以从街头商机中寻找新机会，或休整后再战职场。",
312	    "info",
313	  );
314	
315	  // 关闭弹窗
316	  document.querySelector(".modal-overlay")?.remove();
317	  currentTab = "actions";
318	  renderAll();
319	}
