171	function tickInvestmentDaily(state) {
172	  const inv = state.investment;
173	  if (!inv || inv.lastTickDay >= state.player.day) return;
174	  inv.lastTickDay = state.player.day;
175	  for (const s of INV_STOCKS) {
176	    const m = inv.stockMarket[s.symbol];
177	    if (!m) continue;
178	    m.price = Math.max(
179	      0.5,
180	      m.price * (1 + s.trend + (Math.random() - 0.5) * 2 * s.volatility),
