328	/** 计算能全部买入的股数（按当前价） */
329	function calcMaxBuyShares(symbol) {
330	  const state = StateManager.getState();
331	  const market = state.corporate.stockMarket[symbol];
332	  if (!market || market.price <= 0) return 0;
333	  // 保留 1 元，避免精度问题
334	  const cash = Math.max(0, state.resources.cash - 1);
335	  return Math.floor(cash / market.price);
336	}
