/**
 * 绩效考核系统
 *
 * 综合评分 = KPI×0.35 + 能力×0.25 + 向上管理×0.20 + 人缘×0.15 + 团队×0.05
 * 评级 = 在20个模拟同事中的百分位排名
 */

function calculatePerfScore(state) {
  const c = state.player.corporate;
  const rank = state.corporate.rank;
  const isLowRank = rank === "P5" || rank === "P6";

  // 职级分段权重
  let score = 0;
  if (isLowRank) {
    // P5/P6 执行层: KPI(70%) + 向上管理(30%)
    score += c.kpi * 0.7;
    score += c.upwardMgmt * 0.3;
  } else {
    // P7+ 管理层: KPI(40%) + 向上管理(60%)
    score += c.kpi * 0.4;
    score += c.upwardMgmt * 0.6;
  }

  // 团队贡献 (P7+)
  if (state.corporate.team.length > 0) {
    const avgProd =
      state.corporate.team.reduce((s, m) => s + (m.productivity || 5), 0) /
      state.corporate.team.length;
    score += avgProd * 0.05;
  }

  // 惩罚项
  if (c.hair < 30) score -= 15;
  else if (c.hair < 50) score -= 5;
  if (c.dignity < 20) score -= 20;
  else if (c.dignity < 40) score -= 8;
  if (c.risk > 70) score -= 15;
  else if (c.risk > 50) score -= 5;

  // 奖励项
  if (c.dignity > 80) score += 5;
  if (c.popularity > 80) score += 5;

  // Q4冲刺加成（在 endQuarter 中设置）
  if (state.flags.q4Sprint) {
    score *= 1.1;
  }

  // 随机方差 ±8%
  score += (Math.random() - 0.5) * score * 0.16;
  score = Math.max(0, Math.min(100, score));

  return { score: Math.round(score) };
}

function assignGrade(rawScore, state) {
  // 生成20个模拟同事的分数（围绕玩家分数聚类）
  const peerScores = [];
  const base = rawScore;
  for (let i = 0; i < 20; i++) {
    let ps = base + (Math.random() - 0.5) * 35;
    ps = Math.max(5, Math.min(100, ps));
    peerScores.push(Math.round(ps));
  }

  const allScores = [...peerScores, rawScore];
  allScores.sort((a, b) => b - a);
  const rank = allScores.indexOf(rawScore);
  const percentile = rank / allScores.length;

  let grade;
  if (rawScore < 25) grade = "C";
  else if (percentile < 0.05) grade = "S+";
  else if (percentile < 0.15) grade = "S";
  else if (percentile < 0.5) grade = "A";
  else if (percentile < 0.85) grade = "B";
  else grade = "C";

  // 人缘惩罚：<40 封顶 A, <20 再降一级
  const pop = state.player.corporate.popularity;
  if (pop < 20 && grade !== "C") {
    const gradeOrder = ["C", "B", "A", "S", "S+"];
    const idx = gradeOrder.indexOf(grade);
    if (idx > 0) grade = gradeOrder[idx - 1];
  } else if (pop < 40 && (grade === "S" || grade === "S+")) {
    grade = "A";
  }

  return {
    grade,
    score: rawScore,
    peerAvg: Math.round(
      peerScores.reduce((a, b) => a + b, 0) / peerScores.length,
    ),
    percentile: Math.round((1 - percentile) * 100),
  };
}

function getGradeColor(grade) {
  return (
    { "S+": "#ff6b6b", S: "#feca57", A: "#48dbfb", B: "#c8d6e5", C: "#ff9ff3" }[
      grade
    ] || "#ccc"
  );
}

function getGradeBonus(grade) {
  return { "S+": 3, S: 2, A: 1.5, B: 1, C: 0 }[grade] || 0;
}

/**
 * 晋升判定引擎
 */

function checkPromotion(state) {
  const rank = state.corporate.rank;
  if (rank === "P10") return null;

  const rankData = CORP_RANKS[rank];
  if (!rankData || !rankData.next) return null;

  const reqs = rankData.promotionReqs;
  const c = state.player.corporate;
  const corp = state.corporate;

  // 年龄检查
  if (state.player.age < rankData.minAge) return null;

  // 能力
  if (reqs.minAbility && c.ability < reqs.minAbility) return null;

  // 向上管理
  if (reqs.minUpward && c.upwardMgmt < reqs.minUpward) return null;

  // 人缘
  if (reqs.minPopularity && c.popularity < reqs.minPopularity) return null;

  // 绩效要求
  const recentPerfs = corp.perfHistory.slice(-3);
  if (reqs.minGrade && recentPerfs.length > 0) {
    const latestGrade = recentPerfs[recentPerfs.length - 1].grade;
    if (!gradeMeetsMin(latestGrade, reqs.minGrade)) return null;
  }

  // 团队人数 (P7+)
  if (reqs.minTeamSize && corp.team.length < reqs.minTeamSize) return null;

  // 重大项目 (P7+)
  if (
    reqs.minProjects &&
    (corp.completedProjects || []).length < reqs.minProjects
  )
    return null;

  // P10特殊判定
  if (rank === "P9") {
    let chance = 0.6;
    chance += c.popularity * 0.002;
    chance += c.upwardMgmt * 0.002;
    if (Math.random() > chance) {
      StateManager.addMessage("🏛️ 董事会投票未通过...下次再试。", "warning");
      return null;
    }
  }

  return rankData.next;
}

function applyPromotion(state, newRank) {
  const oldRank = state.corporate.rank;
  state.corporate.rank = newRank;
  const rankData = CORP_RANKS[newRank];

  // 晋升奖励
  state.player.corporate.ability = Math.min(
    100,
    state.player.corporate.ability + 5,
  );
  state.player.corporate.hair = Math.min(100, state.player.corporate.hair + 10);
  state.player.corporate.dignity = Math.min(
    100,
    state.player.corporate.dignity + 10,
  );
  state.player.corporate.kpi = Math.min(150, state.player.corporate.kpi + 15);

  StateManager.addMessage(
    `🎉 恭喜晋升！${CORP_RANKS[oldRank].name} → ${rankData.name}！月薪调整为 ¥${rankData.baseSalary.toLocaleString()}`,
    "success",
  );

  if (newRank === "P10") {
    checkCorpWinConditions(state);
  }
}

function gradeMeetsMin(grade, minGrade) {
  const grades = ["C", "B", "A", "S", "S+"];
  return grades.indexOf(grade) >= grades.indexOf(minGrade);
}

function getPromotionProgress(state) {
  const rank = state.corporate.rank;
  if (rank === "P10") return { done: true, text: "已是最高职级！" };

  const rankData = CORP_RANKS[rank];
  if (!rankData) return { done: false, text: "无法判定" };

  const reqs = rankData.promotionReqs;
  const c = state.player.corporate;
  const corp = state.corporate;

  const checks = [];
  if (reqs.minAbility)
    checks.push({ label: "能力", current: c.ability, target: reqs.minAbility });
  if (reqs.minUpward)
    checks.push({
      label: "向上管理",
      current: c.upwardMgmt,
      target: reqs.minUpward,
    });
  if (reqs.minPopularity)
    checks.push({
      label: "人缘",
      current: c.popularity,
      target: reqs.minPopularity,
    });
  if (reqs.minTeamSize)
    checks.push({
      label: "团队人数",
      current: corp.team.length,
      target: reqs.minTeamSize,
    });
  if (reqs.minProjects)
    checks.push({
      label: "重大项目",
      current: (corp.completedProjects || []).length,
      target: reqs.minProjects,
    });

  const allMet = checks.every((ch) => ch.current >= ch.target);
  return { done: allMet, checks, nextRank: rankData.next };
}

/**
 * 交易系统 — 买卖商品、价格波动、批发进货
 *
 * 提供: buyGood(), sellGood(), buyWholesale(), updatePrices()
 */

/** 玩家购买商品 */
function buyGood(goodId, qty) {
  const state = StateManager.getState();
  const good = getGoodById(goodId);
  if (!good) {
    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
    return false;
  }

  const locKey = state.trade.currentLocation;
  const price = getCurrentPrice(locKey, goodId);

  // 销售技能折扣（最高15%）
  const salesLvl = state.skills.sales.level || 0;
  const discount = Math.min(0.15, salesLvl * 0.002);
  const totalCost = Math.round(price * qty * (1 - discount) * 100) / 100;

  // 检查现金
  if (state.resources.cash < totalCost) {
    StateManager.addMessage(
      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}，你只有 ¥${state.resources.cash}。`,
      "danger",
    );
    return false;
  }

  // 检查背包容量
  const currentItems = state.inventory.items.reduce(
    (sum, item) => sum + item.qty,
    0,
  );
  if (currentItems + qty > state.inventory.capacity) {
    StateManager.addMessage(
      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
      "danger",
    );
    return false;
  }

  // 扣钱
  state.resources.cash -= totalCost;

  // 加入背包
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (existing) {
    existing.qty += qty;
    existing.boughtAt = locKey;
  } else {
    state.inventory.items.push({ id: goodId, qty, boughtAt: locKey });
  }

  // 买入后该商品在当地涨价 1~3%
  const buyDelta = 0.01 + Math.random() * 0.02;
  adjustPriceAfterTrade(locKey, goodId, buyDelta);
  const newPrice = getCurrentPrice(locKey, goodId);

  StateManager.addMessage(
    `🛒 购买了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalCost.toFixed(1)}。${newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : ""}`,
    "success",
  );
  return true;
}

/** 玩家卖出商品 */
function sellGood(goodId, qty) {
  const state = StateManager.getState();
  const good = getGoodById(goodId);
  if (!good) {
    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
    return false;
  }

  // 检查背包
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (!existing || existing.qty < qty) {
    StateManager.addMessage(`⚠️ 背包中没有足够的${good.name}！`, "danger");
    return false;
  }

  const locKey = state.trade.currentLocation;
  let price = getCurrentPrice(locKey, goodId);

  // 同地转卖惩罚：如果卖出地点就是购买地点，售价打7折
  let sameLocationPenalty = false;
  if (existing.boughtAt === locKey) {
    price = Math.round(price * 0.7 * 100) / 100;
    sameLocationPenalty = true;
  }

  // 销售技能溢价（最高15%）
  const salesLvl = state.skills.sales.level || 0;
  const premium = Math.min(0.15, salesLvl * 0.002);
  const totalEarned = Math.round(price * qty * (1 + premium) * 100) / 100;

  // 加钱
  state.resources.cash += totalEarned;
  state.resources.totalEarned += totalEarned;

  // 从背包移除
  existing.qty -= qty;
  if (existing.qty <= 0) {
    state.inventory.items = state.inventory.items.filter(
      (i) => i.id !== goodId,
    );
  }

  // 低买高卖时显示利润
  const buyPrice = getAvgBuyPrice(state, goodId); // 估算买入价
  let profitMsg = "";
  if (sameLocationPenalty) {
    profitMsg = " ⚠️ 同地转卖，贬值严重！";
  } else if (buyPrice > 0) {
    const profit = totalEarned - buyPrice * qty;
    if (profit > 0) {
      profitMsg = ` 📈 获利 ¥${profit.toFixed(1)}！`;
    } else if (profit < 0) {
      profitMsg = ` 📉 亏损 ¥${Math.abs(profit).toFixed(1)}。`;
    }
  }

  // 卖出后该商品在当地降价 1~3%
  const sellDelta = -(0.01 + Math.random() * 0.02);
  adjustPriceAfterTrade(locKey, goodId, sellDelta);
  const newPrice = getCurrentPrice(locKey, goodId);
  const priceMsg =
    newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : "";

  StateManager.addMessage(
    `💰 卖出了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalEarned.toFixed(1)}。${profitMsg}${priceMsg}`,
    "success",
  );
  return true;
}

/** 批发进货（批发市场专属） */
function buyWholesale(goodId, qty) {
  const state = StateManager.getState();
  const good = getGoodById(goodId);
  if (!good) {
    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
    return false;
  }

  const locKey = state.trade.currentLocation;
  const price = getCurrentPrice(locKey, goodId);

  // 批发折扣：批发市场的价格 × 0.7（批量价）
  const wholesalePrice = Math.round(price * 0.7 * 100) / 100;
  const totalCost = Math.round(wholesalePrice * qty * 100) / 100;

  // 最低起批量
  if (qty < 5) {
    StateManager.addMessage("⚠️ 批发最少购买5件。", "warning");
    return false;
  }

  // 检查现金
  if (state.resources.cash < totalCost) {
    StateManager.addMessage(
      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}。`,
      "danger",
    );
    return false;
  }

  // 检查背包
  const currentItems = state.inventory.items.reduce(
    (sum, item) => sum + item.qty,
    0,
  );
  if (currentItems + qty > state.inventory.capacity) {
    StateManager.addMessage(
      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
      "danger",
    );
    return false;
  }

  // 扣钱
  state.resources.cash -= totalCost;

  // 记录买入价（用于后续利润计算）
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (existing) {
    // 加权平均买入价
    const oldTotal = (existing.avgBuyPrice || wholesalePrice) * existing.qty;
    const newTotal = wholesalePrice * qty;
    existing.qty += qty;
    existing.boughtAt = locKey;
    existing.avgBuyPrice =
      Math.round(((oldTotal + newTotal) / existing.qty) * 100) / 100;
  } else {
    state.inventory.items.push({
      id: goodId,
      qty,
      avgBuyPrice: wholesalePrice,
      boughtAt: locKey,
    });
  }

  StateManager.addMessage(
    `📦 批发进货 ${qty}${good.unit}${good.name}，批发价 ¥${wholesalePrice.toFixed(1)}/件，共 ¥${totalCost.toFixed(1)}。`,
    "success",
  );
  return true;
}

/** 快速出售（从背包里选一个商品卖） */
function quickSell(goodId) {
  const state = StateManager.getState();
  const existing = state.inventory.items.find((i) => i.id === goodId);
  if (!existing || existing.qty <= 0) {
    StateManager.addMessage(`⚠️ 背包中没有该商品。`, "warning");
    return false;
  }
  const qty = Math.min(existing.qty, 1); // 默认卖1个
  return sellGood(goodId, qty);
}

/** 交易后动态调价：买入涨价，卖出降价 */
function adjustPriceAfterTrade(locKey, goodId, delta) {
  const state = StateManager.getState();
  const good = getGoodById(goodId);
  if (!good) return;
  const prices = state.trade.goodsPrices[locKey];
  if (!prices) return;
  const oldPrice = prices[goodId] || good.basePrice;
  const change = oldPrice * delta;
  let newPrice = oldPrice + change;
  // 限制范围
  newPrice = Math.max(
    good.basePrice * 0.3,
    Math.min(good.basePrice * 5, newPrice),
  );
  newPrice = Math.round(newPrice * 100) / 100;
  prices[goodId] = newPrice;
}

/** 获取当前地点某商品的零售价 */
function getCurrentPrice(locKey, goodId) {
  const state = StateManager.getState();
  const prices = state.trade.goodsPrices[locKey];
  if (prices && prices[goodId] !== undefined) {
    return prices[goodId];
  }
  const good = getGoodById(goodId);
  return good ? good.basePrice : 1;
}

/** 获取某商品在所有地点的最低价格（用于价格对比） */
function getLowestPrice(goodId) {
  const state = StateManager.getState();
  let lowest = Infinity;
  let lowestLoc = null;
  for (const locKey of Object.keys(LOCATIONS)) {
    const prices = state.trade.goodsPrices[locKey] || {};
    const price = prices[goodId];
    if (price && price < lowest) {
      lowest = price;
      lowestLoc = locKey;
    }
  }
  return { price: lowest, location: lowestLoc };
}

/** 获取某商品在所有地点的最高价格 */
function getHighestPrice(goodId) {
  const state = StateManager.getState();
  let highest = 0;
  let highestLoc = null;
  for (const locKey of Object.keys(LOCATIONS)) {
    const prices = state.trade.goodsPrices[locKey] || {};
    const price = prices[goodId];
    if (price && price > highest) {
      highest = price;
      highestLoc = locKey;
    }
  }
  return { price: highest, location: highestLoc };
}

/** 估算平均买入价 */
function getAvgBuyPrice(state, goodId) {
  const item = state.inventory.items.find((i) => i.id === goodId);
  return item ? item.avgBuyPrice || 0 : 0;
}

/** 更新所有地点所有商品的价格（每3天调用一次） */
function updateAllPrices(state) {
  for (const locKey of Object.keys(LOCATIONS)) {
    const loc = LOCATIONS[locKey];
    // 确保价格对象存在
    if (!state.trade.goodsPrices[locKey]) {
      state.trade.goodsPrices[locKey] = {};
    }
    for (const good of GOODS) {
      let price = good.basePrice;

      // 1. 地点倍率
      if (loc.priceMod && loc.priceMod[good.id]) {
        price *= loc.priceMod[good.id];
      }

      // 2. 随机波动 ±25%
      const fluctuation = 0.75 + Math.random() * 0.5;
      price *= fluctuation;

      // 3. 均值回归（10%向旧价格靠拢）
      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
      price = price + (oldPrice - price) * 0.1;

      // 4. 限制在合理范围
      price = Math.max(
        good.basePrice * 0.25,
        Math.min(good.basePrice * 6, price),
      );
      price = Math.round(price * 100) / 100;

      state.trade.goodsPrices[locKey][good.id] = price;
    }
  }
  state.trade.lastPriceUpdate = state.player.day;
}

/**
 * 新手引导系统
 *
 * 首次进入游戏时弹出逐步教程，引导玩家了解基本 UI 和操作。
 * 用 localStorage 标记已完成引导，不会再次出现。
 * 可随时在帮助菜单中重新触发。
 */

const TUTORIAL_KEY = "city_life_tutorial_done";

/** 检查教程是否已完成 */
function isTutorialDone() {
  try {
    return localStorage.getItem(TUTORIAL_KEY) === "1";
  } catch (e) {
    return false;
  }
}

/** 标记教程完成 */
function markTutorialDone() {
  try {
    localStorage.setItem(TUTORIAL_KEY, "1");
  } catch (e) {
    /* 静默 */
  }
}

/** 重置教程（允许重新触发） */
function resetTutorial() {
  try {
    localStorage.removeItem(TUTORIAL_KEY);
  } catch (e) {
    /* 静默 */
  }
}

/**
 * 启动新手引导
 * 在 startNewGame() 之后调用。
 */
function startTutorial() {
  if (isTutorialDone()) return;

  const steps = [
    {
      title: "🏙️ 欢迎来到城市浮生记！",
