/** 逐步展示引导 */
function showTutorialStep(steps, index) {
  if (index >= steps.length) {
    // 全部完成
    cleanupHighlight();
    markTutorialDone();
    StateManager.addMessage(
      "✅ 新手引导完成！点击 ❓ 帮助按钮可随时回顾。",
      "success",
    );
    return;
  }

  const step = steps[index];
  const isFirst = index === 0;
  const isLast = index === steps.length - 1;

  // 高亮目标区域
  if (step.highlight) {
    highlightElement(step.highlight);
  } else {
    cleanupHighlight();
  }

  const buttons = [
    {
      text: isFirst ? "跳过引导" : "← 上一步",
      cls: isFirst ? "" : "",
      callback: () => {
        if (isFirst) {
          cleanupHighlight();
          markTutorialDone();
          StateManager.addMessage(
            "💡 可以随时点击 ❓ 帮助按钮查看游戏指南。",
            "info",
          );
        } else {
          showTutorialStep(steps, index - 1);
        }
      },
    },
    {
      text: isLast ? "🎯 开始游戏！" : "下一步 →",
      cls: "btn-primary",
      callback: () => {
        showTutorialStep(steps, index + 1);
      },
    },
  ];

  showModal({
    title: `${index + 1}/${steps.length} ${step.title}`,
    body: step.body,
    buttons,
  });

  // 为引导弹窗添加特殊样式
  setTimeout(() => {
    const overlay = document.querySelector(".modal-overlay");
    if (overlay) {
      overlay.classList.add("tutorial-overlay");
      const box = overlay.querySelector(".modal-box");
      if (box) box.classList.add("tutorial-box");
    }
  }, 10);
}

/** 高亮页面元素 */
function highlightElement(selector) {
  cleanupHighlight();
  const el = document.querySelector(selector);
  if (!el) return;

  const hl = document.createElement("div");
  hl.className = "tutorial-highlight";
  hl.id = "tutorial-highlight";

  const rect = el.getBoundingClientRect();
  hl.style.cssText = `
    position: fixed;
    top: ${rect.top - 6}px;
    left: ${rect.left - 6}px;
    width: ${rect.width + 12}px;
    height: ${rect.height + 12}px;
    border: 3px solid var(--accent);
    border-radius: 10px;
    pointer-events: none;
    z-index: 999;
    box-shadow: 0 0 25px rgba(102,126,234,0.5), inset 0 0 25px rgba(102,126,234,0.08);
    animation: tutorial-pulse 1.5s ease-in-out infinite;
  `;
  document.body.appendChild(hl);
}

/** 清除高亮 */
function cleanupHighlight() {
  const existing = document.getElementById("tutorial-highlight");
  if (existing) existing.remove();
  // 同时清除其他可能的残留
  document.querySelectorAll(".tutorial-highlight").forEach((e) => e.remove());
}

// 全局挂载
if (typeof window !== "undefined") {
  Object.assign(window, {
    startTutorial,
    isTutorialDone,
    markTutorialDone,
    resetTutorial,
    showTutorialStep,
    highlightElement,
    cleanupHighlight,
    TUTORIAL_KEY,
  });
}

